class MeinStack
{
    private Knoten? oben;
    public int Count { get; private set; }

    public void Push(int wert)
    {
        var neu = new Knoten(wert);
        neu.Next = oben;
        oben = neu;
        Count++;
    }

    public int Pop()
    {
        if (oben == null)
            throw new InvalidOperationException(
                "Stack ist leer");
        int wert = oben.Wert;
        oben = oben.Next;
        Count--;
        return wert;
    }

    public int Peek()
    {
        if (oben == null)
            throw new InvalidOperationException(
                "Stack ist leer");
        return oben.Wert;
    }
}

var verlauf = new Stack<string>();
verlauf.Push("/start");
verlauf.Push("/termine");
verlauf.Push("/mensa");

// Zurück-Button
string weg = verlauf.Pop();
Console.WriteLine($"Weg von {weg}");
Console.WriteLine(verlauf.Peek());
Console.WriteLine(verlauf.Count);
foreach (string seite in verlauf)
    Console.Write(seite + " ");
// Ausgabe:
// Weg von /mensa
// /termine
// 2
// /termine /start

static bool Korrekt(string text)
{
    string auf = "([{", zu = ")]}";
    var st = new Stack<char>();
    foreach (char c in text)
    {
        if (auf.Contains(c))
            st.Push(c);
        else if (zu.Contains(c))
        {
            if (st.Count == 0)
                return false;
            int i = zu.IndexOf(c);
            if (st.Pop() != auf[i])
                return false;
        }
    }
    return st.Count == 0;
}

Console.WriteLine(Korrekt("a[i] = (b+c);"));
Console.WriteLine(Korrekt("{ (] }"));
Console.WriteLine(Korrekt("((x)"));
// Ausgabe:
// True
// False
// False

